await page.goto('/login');
await expect(page.getByRole('main').first()).toBeVisible();

// Find the full-viewport landing wrapper(s) (large elements near the top of the DOM) and read their overflow.
const clipping = await page.evaluate(() => {
  const vw = window.innerWidth, vh = window.innerHeight;
  const out = [];
  const walk = (el, depth) => {
    if (depth > 4) return;
    const cs = getComputedStyle(el);
    const r = el.getBoundingClientRect();
    if (r.width >= vw * 0.9 && r.height >= vh * 0.5) {
      out.push(cs.overflowX + '|' + cs.overflowY);
    }
    for (const c of el.children) walk(c, depth + 1);
  };
  walk(document.body, 0);
  return out;
});
const clips = clipping.some(v => /hidden|clip/.test(v));
if (!clips) {
  throw new Error('Landing page wrapper does not clip overflow: ' + JSON.stringify(clipping));
}
